import random

# Generator for binary blob inputs targeting VSTRING/VBUF operations.
# Produces valid arbitrary byte sequences with varied patterns and sizes.


def _rand_ascii(r: random.Random, n: int) -> bytes:
    # Printable ASCII plus space
    alphabet = [ord(' ')] + list(range(33, 127))
    return bytes(r.choice(alphabet) for _ in range(n))


def _rand_utf8ish(r: random.Random, n: int) -> bytes:
    # Generate mostly-valid UTF-8 sequences mixed with ASCII
    # Avoid surrogate range 0xD800..0xDFFF which is invalid for UTF-8 encoding
    out = bytearray()
    while len(out) < n:
        choice = r.random()
        rem = n - len(out)
        if choice < 0.6:
            out.append(r.randrange(0x20, 0x7F))
        elif choice < 0.75 and rem >= 2:
            cp = r.randrange(0x80, 0x800)
            out += chr(cp).encode('utf-8')
        elif choice < 0.9 and rem >= 3:
            # pick from BMP excluding surrogates
            while True:
                cp = r.randrange(0x800, 0x10000)
                if not (0xD800 <= cp <= 0xDFFF):
                    break
            out += chr(cp).encode('utf-8')
        elif rem >= 4:
            cp = r.randrange(0x10000, 0x110000)
            out += chr(cp).encode('utf-8')
        else:
            out.append(r.randrange(0x00, 0x100))
    if len(out) > n:
        del out[n:]
    return bytes(out)


def _rand_binary(r: random.Random, n: int) -> bytes:
    return r.randbytes(n) if hasattr(r, 'randbytes') else bytes(r.getrandbits(8) for _ in range(n))


def _pattern_repeats(r: random.Random, n: int) -> bytes:
    pat_len = r.choice([1, 2, 3, 4, 8, 16, 32])
    pat_types = [
        lambda m: bytes([r.randrange(256) for _ in range(m)]),
        lambda m: bytes((i % 256 for i in range(m))),
        lambda m: bytes((255 - (i % 256) for i in range(m))),
        lambda m: b"\x00" * m,
        lambda m: b"\xFF" * m,
        lambda m: _rand_ascii(r, m),
    ]
    pat = r.choice(pat_types)(pat_len)
    reps = (n + pat_len - 1) // pat_len
    return (pat * reps)[:n]


def _mixed_blocks(r: random.Random, n: int) -> bytes:
    blocks = []
    remaining = n
    gens = [_rand_ascii, _rand_utf8ish, _rand_binary, _pattern_repeats]
    while remaining > 0:
        block_size = r.randint(1, max(1, min(256, remaining)))
        g = r.choice(gens)
        if g is _pattern_repeats:
            blocks.append(_pattern_repeats(r, block_size))
        else:
            blocks.append(g(r, block_size))
        remaining -= block_size
    return b"".join(blocks)


def _inject_nuls_and_edges(r: random.Random, data: bytes) -> bytes:
    if not data:
        return data
    b = bytearray(data)
    L = len(b)
    positions = set()
    for pos in [0, L // 2, L - 1]:
        if 0 <= pos < L:
            positions.add(pos)
    for _ in range(min(8, L)):
        positions.add(r.randrange(0, L))
    for pos in positions:
        choice = r.random()
        if choice < 0.4:
            b[pos] = 0x00
        elif choice < 0.7:
            b[pos] = 0xFF
        elif choice < 0.85:
            b[pos] = 0x7F
        else:
            b[pos] = (pos & 0xFF)
    return bytes(b)


def _choose_length(r: random.Random) -> int:
    lens = [0, 1, 2, 3, 4, 7, 8, 15, 16, 31, 32, 63, 64, 65, 100, 128, 255, 256, 512, 768, 1000, 1023, 1024]
    if r.random() < 0.7:
        return r.choice(lens)
    else:
        return r.randint(0, 1024)


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    mode = r.choice(['ascii', 'utf8', 'binary', 'repeat', 'mixed'])
    n = _choose_length(r)

    if mode == 'ascii':
        data = _rand_ascii(r, n)
    elif mode == 'utf8':
        data = _rand_utf8ish(r, n)
    elif mode == 'binary':
        data = _rand_binary(r, n)
    elif mode == 'repeat':
        data = _pattern_repeats(r, n)
    else:
        data = _mixed_blocks(r, n)

    if r.random() < 0.8:
        data = _inject_nuls_and_edges(r, data)

    if data and r.random() < 0.3:
        data = data[:-1] + b"\x00"

    if len(data) > 1024:
        data = data[:1024]

    return data
